import json,pathlib,copy,gzip
r=pathlib.Path('work/research-2026');rows=json.load(open(r/'general-round30-c-input.json'));old=json.load(open(r/'reviewed.json'));p={}
for i,k in {7:'ef6df18446e8a34e',9:'0270f94e9f580488'}.items():
 row=rows[i];v=copy.deepcopy(old[k]);v['name']+=(' (via Cardinal Point Partners)' if i==9 else '');v['identity_evidence']='Original client label compared with existing individually researched identity. '+v['identity_evidence'];v['notes']+=' Source reference '+k+'.';v['sources']+=row.get('profile',{}).get('sources',[])
