def add(i,name,desc,web,kind='Company',own='Unknown',sources=[],notes='',legal='',outcome=None,featured=False):
 row=rows[i];filing=json.load(gzip.open('lobbying-map/public/data/reports/'+row['id'][:2]+'.json.gz','rt'))[row['id']][0]
 p[row['id']]=dict(name=name,description=desc,website=web,kind=kind,ownership=own,legal_form=legal,review_outcome=outcome or ('partial' if own=='Unknown' else 'confirmed'),featured=featured,identity_evidence='Disclosed name and activity compared with the cited primary organization evidence. '+notes,notes=notes,sources=[dict(url='https://lda.gov/filings/public/filing/'+filing['id']+'/print/',label='Original lobbying disclosure',claim='Original reported label and filing provenance retained; filing alone does not establish ownership.')]+[dict(url=u,label='Organization evidence',claim=c) for u,c in sources])
